create table public.chat_file_library(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,uploader_id uuid not null references auth.users(id) on delete cascade,saved_by uuid references auth.users(id) on delete set null,source_message_id uuid references public.chat_messages(id) on delete set null,object_path text not null,file_name text not null,mime_type text not null,byte_size bigint not null,created_at timestamptz not null default now(),unique(conversation_id,object_path));
alter table public.chat_file_library enable row level security;revoke all on public.chat_file_library from anon,authenticated;grant select on public.chat_file_library to authenticated;
create policy file_library_member on public.chat_file_library for select to authenticated using(public.is_conversation_member(conversation_id));
create or replace function public.retain_chat_library_file(target_attachment_id uuid) returns void language plpgsql security definer set search_path='' as $$declare a public.chat_attachments;begin
 select x.* into a from public.chat_attachments x join public.chat_messages m on m.id=x.message_id where x.id=target_attachment_id and public.is_conversation_member(x.conversation_id) and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now());
 if a.id is null or not exists(select 1 from public.conversation_members where conversation_id=a.conversation_id and user_id=auth.uid() and role in('owner','admin')) then raise exception 'Only a conversation admin can retain live files in its library';end if;
 insert into public.chat_file_library(conversation_id,uploader_id,saved_by,source_message_id,object_path,file_name,mime_type,byte_size) values(a.conversation_id,a.uploader_id,auth.uid(),a.message_id,a.object_path,a.file_name,a.mime_type,a.byte_size) on conflict do nothing;
end;$$;
create or replace function public.remove_chat_library_file(library_file_id uuid) returns void language plpgsql security definer set search_path='' as $$declare c uuid;begin
 select conversation_id into c from public.chat_file_library where id=library_file_id;
 if c is null or not exists(select 1 from public.conversation_members where conversation_id=c and user_id=auth.uid() and role in('owner','admin')) then raise exception 'Conversation admin required';end if;
 delete from public.chat_file_library where id=library_file_id;
end;$$;
create or replace function public.enqueue_chat_media_cleanup() returns trigger language plpgsql security definer set search_path='' as $$begin
 if old.object_path is not null and length(old.object_path)>0 and not exists(select 1 from public.chat_file_library where object_path=old.object_path) then insert into public.storage_cleanup_queue(bucket_id,object_path) values('chat-media',old.object_path) on conflict do nothing;end if;
 if old.thumbnail_path is not null and length(old.thumbnail_path)>0 then insert into public.storage_cleanup_queue(bucket_id,object_path) values('chat-media',old.thumbnail_path) on conflict do nothing;end if;return old;
end;$$;
create or replace function public.queue_removed_library_file() returns trigger language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from public.chat_attachments where object_path=old.object_path) and not exists(select 1 from public.chat_file_library where object_path=old.object_path) then insert into public.storage_cleanup_queue(bucket_id,object_path) values('chat-media',old.object_path) on conflict do nothing;end if;return old;
end;$$;
create trigger removed_library_cleanup after delete on public.chat_file_library for each row execute function public.queue_removed_library_file();
alter policy "chat media members can read" on storage.objects to authenticated using(bucket_id='chat-media' and exists(select 1 from public.conversation_members cm where cm.conversation_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid())) and((storage.foldername(name))[2]=(select auth.uid())::text or exists(select 1 from public.chat_attachments a join public.chat_messages m on m.id=a.message_id where a.object_path=name) or exists(select 1 from public.chat_file_library l where l.object_path=name and public.is_conversation_member(l.conversation_id))));
create table public.chat_vault_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,origin_message_id uuid not null,source_message_id uuid references public.chat_messages(id) on delete set null,body text not null,collection text not null default 'Saved' check(length(collection) between 1 and 80),note text not null default '' check(length(note)<=500),created_at timestamptz not null default now(),unique(user_id,origin_message_id));
alter table public.chat_vault_items enable row level security;revoke all on public.chat_vault_items from anon,authenticated;grant select,update,delete on public.chat_vault_items to authenticated;
create policy vault_items_own on public.chat_vault_items for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create or replace function public.set_chat_bookmark(target_message_id uuid,should_save boolean) returns void language plpgsql security definer set search_path='' as $$declare m public.chat_messages;begin
 if auth.uid() is null then raise exception 'Sign in required';end if;
 if not should_save then delete from public.message_bookmarks where user_id=auth.uid() and message_id=target_message_id;delete from public.chat_vault_items where user_id=auth.uid() and origin_message_id=target_message_id;return;end if;
 select * into m from public.chat_messages where id=target_message_id and public.is_conversation_member(conversation_id) and deleted_at is null and recalled_at is null and(expires_at is null or expires_at>now());if m.id is null then raise exception 'Message unavailable';end if;
 insert into public.message_bookmarks(user_id,message_id) values(auth.uid(),target_message_id) on conflict do nothing;
 insert into public.chat_vault_items(user_id,origin_message_id,source_message_id,body) values(auth.uid(),target_message_id,target_message_id,m.body) on conflict do nothing;
end;$$;
create or replace function public.save_chat_vault(target_message_id uuid,collection_name text,private_note text) returns void language plpgsql security definer set search_path='' as $$begin
 if collection_name is null or length(trim(collection_name)) not between 1 and 80 or private_note is null or length(private_note)>500 then raise exception 'Collection: 1–80 characters; note: up to 500';end if;
 perform public.set_chat_bookmark(target_message_id,true);update public.message_bookmarks set collection=trim(collection_name),note=private_note where message_id=target_message_id and user_id=auth.uid();update public.chat_vault_items set collection=trim(collection_name),note=private_note where origin_message_id=target_message_id and user_id=auth.uid();
end;$$;
insert into public.chat_vault_items(user_id,origin_message_id,source_message_id,body,collection,note,created_at) select b.user_id,m.id,m.id,m.body,b.collection,b.note,b.created_at from public.message_bookmarks b join public.chat_messages m on m.id=b.message_id where m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now()) and exists(select 1 from public.conversation_members cm where cm.conversation_id=m.conversation_id and cm.user_id=b.user_id) on conflict do nothing;
create table public.chat_vault_files(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,object_path text not null unique,file_name text not null,mime_type text not null,byte_size bigint not null,collection text not null default 'Files' check(length(collection) between 1 and 80),note text not null default '' check(length(note)<=500),created_at timestamptz not null default now());
alter table public.chat_vault_files enable row level security;revoke all on public.chat_vault_files from anon,authenticated;grant select,update,delete on public.chat_vault_files to authenticated;
create policy vault_files_own on public.chat_vault_files for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('luo-vault','luo-vault',false,52428800,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','audio/mpeg','audio/mp4','audio/ogg','audio/webm','application/pdf','text/plain']);
create policy vault_storage_owned_insert on storage.objects for insert to authenticated with check(bucket_id='luo-vault' and(storage.foldername(name))[1]=(select auth.uid())::text);
create policy vault_storage_owned_read on storage.objects for select to authenticated using(bucket_id='luo-vault' and(storage.foldername(name))[1]=(select auth.uid())::text);
create policy vault_storage_owned_delete on storage.objects for delete to authenticated using(bucket_id='luo-vault' and(storage.foldername(name))[1]=(select auth.uid())::text);
create or replace function public.commit_private_vault_file(uploaded_path text,uploaded_name text,uploaded_type text,uploaded_bytes bigint,collection_name text) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or length(uploaded_name) not between 1 and 255 or length(collection_name) not between 1 and 80 or uploaded_bytes not between 1 and 52428800 or not exists(select 1 from storage.objects o where o.bucket_id='luo-vault' and o.name=uploaded_path and o.owner_id=auth.uid()::text and split_part(o.name,'/',1)=auth.uid()::text and o.metadata->>'mimetype'=uploaded_type and(o.metadata->>'size')::bigint=uploaded_bytes) then raise exception 'Upload a valid private vault file first';end if;
 insert into public.chat_vault_files(user_id,object_path,file_name,mime_type,byte_size,collection) values(auth.uid(),uploaded_path,uploaded_name,uploaded_type,uploaded_bytes,collection_name) on conflict(object_path) do nothing;
end;$$;
create or replace function public.queue_deleted_vault_file() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.storage_cleanup_queue(bucket_id,object_path) values('luo-vault',old.object_path) on conflict do nothing;return old;end;$$;
create trigger deleted_vault_cleanup after delete on public.chat_vault_files for each row execute function public.queue_deleted_vault_file();
create or replace function public.queue_deleted_story_media() returns trigger language plpgsql security definer set search_path='' as $$begin if old.media_path is not null then insert into public.storage_cleanup_queue(bucket_id,object_path) values('luo-stories',old.media_path) on conflict do nothing;end if;return old;end;$$;
create or replace function public.chat_account_storage_paths(target_user_id uuid) returns table(bucket_id text,object_path text) language sql stable security definer set search_path='' as $$select o.bucket_id,o.name from storage.objects o where(o.bucket_id in('avatars','luo-stories','luo-vault') and split_part(o.name,'/',1)=target_user_id::text) or(o.bucket_id='chat-media' and split_part(o.name,'/',2)=target_user_id::text);$$;
revoke all on function public.queue_removed_library_file(),public.queue_deleted_vault_file() from public,anon,authenticated;
revoke all on function public.retain_chat_library_file(uuid),public.remove_chat_library_file(uuid),public.commit_private_vault_file(text,text,text,bigint,text) from public,anon;
grant execute on function public.retain_chat_library_file(uuid),public.remove_chat_library_file(uuid),public.commit_private_vault_file(text,text,text,bigint,text) to authenticated;
create index file_library_conversation_idx on public.chat_file_library(conversation_id,created_at);
create index vault_items_user_idx on public.chat_vault_items(user_id,created_at);
create index vault_files_user_idx on public.chat_vault_files(user_id,created_at);
